  background-color: rgba(66, 133, 244, 0.15) !important;
}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;script src="https://cdn.jsdelivr.net/npm/fullcalendar-scheduler@6.1.15/index.global.min.js"&gt;&lt;/script&gt;
&lt;div id="calendar"&gt;&lt;/div&gt;</code></pre>
</div>
</div>
</p>
<p><strong>UPDATE</strong></p>
<p>Thanks @ADyson for pointing out the requirement.</p>
<p>Through debugging I found that the empty space in lane is covered by <code>.fc-timeline-lane-frame</code> elements (children of <code>.fc-timeline-lane</code>).</p>
<p>The outer scroll area uses <code>.fc-scroller</code> which has no resource data. Events are in <code>.fc-event</code> elements.</p>
<p>I did a two step detection approach. First I checked if the element under the mouse (or it's ancestors) has <code>data-source-id</code>. The empty space is <code>fc-timeline-lane-frame</code> (a child without <code>data-source-id</code>), so traversed up to find the parent lane.</p>
<p>When over the scroller area, used Y coordinate to find which lane's bounds contain the mouse.</p>
<p>Then checked if the lane contains any <code>fc-event</code> elements before highlighting.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>var calendarEl = document.getElementById('calendar');
var currentHoveredResourceId = null;

function highlightResource(resourceId) {
  // only highlight if this resource has events
  const lane = calendarEl.querySelector(`.fc-timeline-lane[data-resource-id="${resourceId}"]`);
  if (!lane) return;

  const hasEvents = lane.querySelector('.fc-event') !== null;
  if (!hasEvents) return;

  calendarEl.querySelectorAll(
    `.fc-timeline-lane[data-resource-id="${resourceId}"],
     .fc-datagrid-cell[data-resource-id="${resourceId}"]`
  ).forEach(el =&gt; el.classList.add('lane-hover'));
}

function unhighlightResource(resourceId) {
  calendarEl.querySelectorAll(
    `.fc-timeline-lane[data-resource-id="${resourceId}"],
     .fc-datagrid-cell[data-resource-id="${resourceId}"]`
  ).forEach(el =&gt; el.classList.remove('lane-hover'));
}

// find resource
function getResourceFromElement(element) {
  // check for resource id
  const direct = element.closest('[data-resource-id]');
  if (direct) return direct.dataset.resourceId;

  // check if in a lane frame
  const laneFrame = element.closest('.fc-timeline-lane-frame');
  if (laneFrame) {
    const lane = laneFrame.closest('.fc-timeline-lane[data-resource-id]');
    if (lane) return lane.dataset.resourceId;
  }

  return null;
}

// find resource at Y coordinate
function getResourceAtY(clientY) {
  const lanes = calendarEl.querySelectorAll('.fc-timeline-lane[data-resource-id]');
  for (const lane of lanes) {
    const rect = lane.getBoundingClientRect();
    if (clientY &gt;= rect.top &amp;&amp; clientY &lt;= rect.bottom) {
      return lane.dataset.resourceId;
    }
  }
  return null;
}

var calendar = new FullCalendar.Calendar(calendarEl, {
  timeZone: 'UTC',
  headerToolbar: {
    left: 'today prev,next',
    center: 'title',
    right: 'resourceTimelineDay,resourceTimelineTenDay'
  },
  initialView: 'resourceTimelineDay',
  scrollTime: '08:00',
  aspectRatio: 1.5,
  views: {
    resourceTimelineDay: {
      buttonText: ':15 slots',
      slotDuration: '00:15'
    },
    resourceTimelineTenDay: {
      type: 'resourceTimeline',
      duration: {
        days: 10
      },
      buttonText: '10 days'
    }
  },
  editable: true,
  resourceAreaHeaderContent: 'Rooms',
  resources: 'https://fullcalendar.io/api/demo-feeds/resources.json?with-nesting&amp;with-colors',
  events: 'https://fullcalendar.io/api/demo-feeds/events.json?single-day&amp;for-resource-timeline',
  viewDidMount: function() {
    calendarEl.addEventListener('mousemove', function(e) {
      let resourceId = null;

      // first element based detection
      resourceId = getResourceFromElement(e.target);

      // fall back to coordinate based detection
      if (!resourceId) {
        resourceId = getResourceAtY(e.clientY);
      }

      if (resourceId !== currentHoveredResourceId) {
        if (currentHoveredResourceId) {
          unhighlightResource(currentHoveredResourceId);
        }
        if (resourceId) {
          highlightResource(resourceId);
        }
        currentHoveredResourceId = resourceId;
      }
    });

    calendarEl.addEventListener('mouseleave', function() {
      if (currentHoveredResourceId) {
        unhighlightResource(currentHoveredResourceId);
        currentHoveredResourceId = null;
      }
    });
  }
});

calendar.render();</code></pre>
