body {
  margin: 0;
  padding: 0;
  font-family: Arial, Helvetica Neue, Helvetica, sans-serif;
  font-size: 14px;
}

#calendar {
  max-width: 1100px;
  margin: 40px auto;
}

.fc-timeline-lane.lane-hover,
.fc-datagrid-cell.lane-hover {
  background-color: rgba(66, 133, 244, 0.15) !important;
}</code></pre>
